import { loader } from "fumadocs-core/source";
import { docs } from "@/.source/server";

/**
 * The Fumadocs content source. Backed by MDX files in `content/docs`.
 * The `.source` directory is generated by `fumadocs-mdx` (see package.json
 * scripts and the `createMDX` plugin in next.config.ts).
 */
export const source = loader({
  baseUrl: "/docs",
  source: docs.toFumadocsSource(),
});
